mapper.select:
WITH org00 AS (SELECT * FROM getOrg(#{companyId}, f_today())) SELECT emp01_person_id AS person_id, emp01_emp_no AS emp_no, emp01_kor_nm AS kor_nm, org00_kor_nm AS org_nm, COALESCE(emp01_lock_yn = 'true', false) AS lock_yn FROM emp03_trans trans INNER JOIN emp01_person ON emp01_person_id = emp03_person_id INNER JOIN org00 ON org00_org_id = emp03_org_code_id WHERE 1=1 AND emp01_company_id = #{companyId}
AND emp01_person_id = #{personId}
AND emp03_trans_cd NOT IN ('800','900') AND emp03_trans_date IN ( SELECT max(emp03_trans_date) FROM emp03_trans WHERE emp03_person_id = emp01_person_id AND emp03_trans_date <= f_today() ) AND org00_mod_date = ( SELECT max(org00_mod_date) FROM org00 WHERE org00_org_id = emp03_org_code_id AND org00_mod_date <= emp03_trans_date ) ORDER BY org00_org_cd, emp03_title_cd, emp01_order_seq

SELECT MAX(sys25_seq)
  FROM sys25_password
 WHERE sys25_company_id = #{companyId}
   AND sys25_person_id = #{personId}

mapper.insert:
INSERT INTO sys25_password
       (sys25_password_id, sys25_company_id, sys25_person_id, sys25_seq, sys25_pwd, sys25_work_date)
SELECT f_create_seq()
     , #{companyId}
     , #{personId}
     , (
         SELECT COALESCE(MAX(sys25_seq),0) + 1
           FROM sys25_password
          WHERE sys25_person_id = #{personId}
       )
     , TO_ENCRYPTS(#{pwd})
     , f_sysdate()

mapper.update:
UPDATE sys25_password
   SET sys25_work_date = f_sysdate()
     , sys25_pwd = TO_ENCRYPTS(#{pwd})
 WHERE sys25_person_id = #{personId}
   AND sys25_company_id = #{companyId}
   AND sys25_seq = #{seq}
